    ["Shows recent awards and other winners for the hovered item."] = "Mostra le assegnazioni recenti e gli altri vincitori per l'oggetto sotto il mouse.",
    ["Simple Loot Council is active for this group - %s is collecting the loot for the council."] = "Simple Loot Council \195\168 attivo per questo gruppo: %s raccoglie il bottino per il consiglio.",
    ["Simple Loot Council is active for this group - %s is collecting the loot, and this addon passes your group-loot rolls for the council to distribute."] = "Simple Loot Council \195\168 attivo per questo gruppo: %s raccoglie il bottino e questo addon passa i tuoi tiri sul bottino di gruppo perch\195\169 il consiglio lo distribuisca.",
    ["Simple Loot Council is active for this raid - %s is collecting the loot for the council."] = "Simple Loot Council \195\168 attivo per questa incursione: %s raccoglie il bottino per il consiglio.",
    ["Simple Loot Council is active for this raid - %s is collecting the loot, and this addon passes your group-loot rolls for the council to distribute."] = "Simple Loot Council \195\168 attivo per questa incursione: %s raccoglie il bottino e questo addon passa i tuoi tiri sul bottino di gruppo perch\195\169 il consiglio lo distribuisca.",
